<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= e($title) ?> — <?= e(site_settings()['siteName']) ?></title><?php if (!in_array(strtolower($_SERVER['HTTP_HOST'] ?? ''), config()['index_hosts'] ?? [], true)): ?><meta name="robots" content="noindex,nofollow"><?php endif; ?><meta name="description" content="<?= e(site_settings()['description']) ?>"><link rel="icon" href="<?= e(gallery_icon_url()) ?>"><link rel="stylesheet" href="<?= e(asset_url('site.css')) ?>"><link rel="stylesheet" href="<?= e(asset_url('prototype.css')) ?>"><?php if (str_starts_with($path, '/admin')): ?><link rel="stylesheet" href="<?= e(asset_url('admin.css')) ?>"><?php endif; ?><script src="<?= e(asset_url('gallery.js')) ?>" defer></script></head>
