<header class="site-header"><a class="brand" href="/" aria-label="<?= e(site_settings()['siteName']) ?> home"><?php if (site_settings()['iconHash']): ?><img class="gallery-brand-icon" src="<?= e(gallery_icon_url()) ?>" alt=""><?php else: ?><span class="brand-mark" aria-hidden="true"><span></span><span></span><span></span></span><?php endif; ?><span><?= e(site_settings()['siteName']) ?></span></a><nav class="main-nav" aria-label="Main navigation"><a href="/">Gallery</a><a href="/?sort=popular#gallery">Top images</a><?php if (!$user): ?><a href="/upload">Upload</a><?php endif; ?><?php if ($user && $user['role'] === 'admin'): ?><a href="/admin">Admin</a><?php endif; ?><?php if ($discordInvite): ?><a href="<?= e($discordInvite) ?>" target="_blank" rel="noopener noreferrer">Discord</a><?php endif; ?></nav><div class="header-account"><?php if ($user): ?><a class="header-cta upload-cta" href="/upload">Upload artwork +</a><a href="/account"><?= e($user['username']) ?></a><form method="post" action="/logout"><?= csrf_field() ?><button class="quiet-button">Sign out</button></form><?php else: ?><a href="/login">Sign in</a><a class="header-cta" href="/register">Register</a><?php endif; ?></div></header>
<?php if ($notFound): ?>
<main class="auth-page"><h1>This page isn’t available</h1><p>The artwork may be unavailable or the address may be incorrect.</p><a href="/">Back to the gallery</a></main>
<?php elseif ($path === '/privacy'): require __DIR__ . '/privacy.php';
elseif ($path === '/about'): ?>
<main class="prototype-about"><p class="eyebrow">COMMUNITY ART GALLERY</p><h1>About <?= e(site_settings()['siteName']) ?></h1><p><?= e(site_settings()['description']) ?></p><h2>Explore the gallery</h2><p>Browse artwork by software, category or artist. Save favorites and leave comments on work you enjoy.</p><h2>Share your work</h2><p>Create an account to upload artwork. New uploads are reviewed by an administrator unless your account has automatic approval.</p><a class="button" href="/">Explore the gallery</a></main>
<?php elseif (in_array($path, ['/login', '/register'], true)): require __DIR__ . '/auth.php';
elseif (in_array($path, ['/account', '/account/password', '/account/notifications'], true)): require __DIR__ . '/account.php';
elseif ($path === '/upload' || ($artwork && str_ends_with($path, '/edit'))): require __DIR__ . '/upload.php';
elseif (str_starts_with($path, '/admin')): require __DIR__ . '/admin.php';
elseif ($artwork): require __DIR__ . '/artwork.php';
else: require __DIR__ . '/gallery.php'; endif; ?>
